import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware to parse session from cookie
function getSession(req) {
  const token = req.cookies?.session_token;
  if (!token) return null;
  // Decode base64 session payload (trusted, set by our auth layer)
  try {
    return JSON.parse(Buffer.from(token, 'base64').toString());
  } catch { return null; }
}

// Rate limiting state (in-memory, per-instance)
const requestCounts = new Map();
function rateLimit(ip) {
  const now = Date.now();
  const entry = requestCounts.get(ip) || { count: 0, reset: now + 60000 };
  if (now > entry.reset) { entry.count = 0; entry.reset = now + 60000; }
  entry.count++;
  requestCounts.set(ip, entry);
  return entry.count > 100;
}

// Input length validation middleware
app.use((req, res, next) => {
  for (const [key, value] of Object.entries(req.query)) {
    if (typeof value === 'string' && value.length > 512) {
      return res.status(400).json({ error: 'Parameter too long' });
    }
  }
  next();
});

// Audit log helper - uses parameterized query (safe)
async function auditLog(action, userId, detail) {
  await pool.query(
    'INSERT INTO audit_log(action, user_id, detail, ts) VALUES($1, $2, $3, NOW())',
    [action, userId, detail]
  );
}

// Search endpoint for internal reporting
app.get('/api/reports/search', async (req, res) => {
  const session = getSession(req);
  if (!session) return res.status(401).json({ error: 'Unauthorized' });

  if (rateLimit(req.ip)) return res.status(429).json({ error: 'Rate limited' });

  const { department, fiscal_year, metric } = req.query;

  // Validate fiscal_year is numeric
  if (fiscal_year && !/^\d{4}$/.test(fiscal_year)) {
    return res.status(400).json({ error: 'Invalid fiscal year' });
  }

  // Validate metric against allowlist
  const allowedMetrics = ['revenue', 'headcount', 'expenses', 'margin'];
  const selectedMetric = allowedMetrics.includes(metric) ? metric : 'revenue';

  // Build query - department filter is vulnerable
  let query = `SELECT department, ${selectedMetric}, fiscal_year, report_id 
               FROM financial_reports 
               WHERE fiscal_year = ${fiscal_year || 2024}`;

  if (department) {
    // Developer note: department comes from dropdown, should be safe
    query += ` AND department = '${department}'`;
  }

  query += ` ORDER BY ${selectedMetric} DESC LIMIT 50`;

  try {
    const result = await pool.query(query);
    await auditLog('report_search', session.user_id, `dept=${department}`);
    res.json({ reports: result.rows });
  } catch (err) {
    // Return generic error (don't leak DB errors)
    console.error('Query failed:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(8080, () => console.log('Listening on 8080'));
